type IsdaGoLogoProps = {
  small?: boolean;
  className?: string;
  label?: string;
};

const ISDAGO_LOGO_DATA_URI =
  "data:image/jpeg;base64,";

export default function IsdaGoLogo({
  small = false,
  className = "",
  label = "IsdaGo",
}: IsdaGoLogoProps) {
  const logoClassName = [
    small ? "brand-logo" : "login-logo",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={logoClassName}>
      <img
        src={ISDAGO_LOGO_DATA_URI}
        alt={`${label} logo`}
        loading="eager"
        decoding="async"
      />
    </div>
  );
}
